<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Shared\Value\Pagination\Slider;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

final class SliderUnitTest extends TestCase
{
    /** @var list<int> sizes requested by each refill read */
    private array $reads = [];

    public static function invalidSizes(): array
    {
        return [
            'zero limit' => [1, 0, 'Page limit must be positive'],
            'negative limit' => [1, -1, 'Page limit must be positive'],
            'zero requested' => [0, 1, 'Requested row count must be positive'],
            'negative requested' => [-1, 1, 'Requested row count must be positive'],
        ];
    }

    #[DataProvider('invalidSizes')]
    public function test_rejects_non_positive_sizes_before_evaluating_rows(int $requested, int $limit, string $message): void
    {
        $this->expectException(InvalidArgumentException::class);
        $this->expectExceptionMessage($message);

        Slider::slide([1], $requested, $limit,
            static fn (int $after, int $size): array => throw new LogicException('Unexpected read'),
            static fn (int $item): bool => throw new LogicException('Unexpected evaluation'));
    }

    public function test_full_first_read_gives_page_and_next_without_refill(): void
    {
        $page = $this->slide(range(1, 100), limit: 20, accept: fn (int $i): bool => true);

        $this->assertSame(range(1, 20), $page->items);
        $this->assertTrue($page->hasNext);
        $this->assertSame([], $this->reads);
    }

    public function test_exactly_full_last_page_has_no_next(): void
    {
        $page = $this->slide(range(1, 20), limit: 20, accept: fn (int $i): bool => true);

        $this->assertSame(range(1, 20), $page->items);
        $this->assertFalse($page->hasNext);
        $this->assertSame([], $this->reads);
    }

    public function test_refill_is_sized_from_observed_ratio_with_margin(): void
    {
        // 21 rows read, 10 accepted (even numbers): 11 missing * 21 / 10 * 1.2 = 27.72 -> 28.
        $page = $this->slide(range(1, 1000), limit: 20, accept: fn (int $i): bool => $i % 2 === 0);

        $this->assertSame(range(2, 40, 2), $page->items);
        $this->assertTrue($page->hasNext);
        $this->assertSame([28], $this->reads);
    }

    public function test_refill_doubles_while_nothing_is_accepted(): void
    {
        $page = $this->slide(range(1, 1000), limit: 20, accept: fn (int $i): bool => $i > 900);

        $this->assertSame(range(901, 920), $page->items);
        $this->assertTrue($page->hasNext);
        $this->assertSame([42, 84, 168, 336, 672], $this->reads); // no ratio yet: each read doubles the previous one
    }

    public function test_refill_is_capped(): void
    {
        $this->slide(range(1, 5000), limit: 20, accept: fn (int $i): bool => $i > 4900);

        $this->assertSame(1000, max($this->reads));
    }

    public function test_stops_when_source_is_exhausted(): void
    {
        $page = $this->slide(range(1, 50), limit: 20, accept: fn (int $i): bool => $i % 10 === 0);

        $this->assertSame([10, 20, 30, 40, 50], $page->items);
        $this->assertFalse($page->hasNext);
    }

    public function test_rows_after_the_extra_accepted_item_are_not_evaluated(): void
    {
        $evaluated = 0;
        $this->slide(range(1, 100), limit: 3, accept: function (int $i) use (&$evaluated): bool {
            $evaluated++;
            return true;
        });

        $this->assertSame(4, $evaluated);
    }

    /**
     * Runs Slider over an in-memory sorted source of ints, reading the first page with the
     * same lookahead the repository adapters use.
     */
    private function slide(array $source, int $limit, Closure $accept): Civi\Lughauth\Shared\Value\Pagination\SlidePage
    {
        $this->reads = [];
        $requested = $limit + max(1, (int) ceil($limit * 0.05));
        $read = function (int $after, int $size) use ($source): array {
            $this->reads[] = $size;
            return array_values(array_slice(array_filter($source, fn (int $i): bool => $i > $after), 0, $size));
        };
        return Slider::slide(array_slice($source, 0, $requested), $requested, $limit, $read, $accept);
    }
}
